fn patterns() -> Result<&'static [Option<ROMol>]> {
    static PATS: std::sync::OnceLock<Vec<Option<ROMol>>> = std::sync::OnceLock::new();
    if let Some(p) = PATS.get() {
        return Ok(p);
    }
    let params = SmartsParserParams::default();
    let mut v: Vec<Option<ROMol>> = (0..167).map(|_| None).collect();
    for &(bit, sma) in PATTERNS {
        v[bit as usize] = Some(
            mol_from_smarts(sma, &params)?
                .ok_or_else(|| RDKitError::invariant("bad MACCS smarts"))?,
        );
    }
    Ok(PATS.get_or_init(|| v))
}

